import java.io.*;
import java.util.*;

public class E {
    static final int MOD = 998_244_353;

    public static void main(String[] args) throws Exception {
        new E().run();
    }

    void run() throws Exception {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        int n = fs.nextInt();
        int m = fs.nextInt();
        int l = fs.nextInt();
        int r = fs.nextInt();

        if ((n & 1) == 1 && (m & 1) == 1) {
            long total = r - l + 1;
            out.println(exp(exp(total, n), m));
            out.flush();
            return;
        }

        int even = r / 2 - (l + 1) / 2 + 1;
        int odd = r - l + 1 - even;
        Matrix base = new Matrix(even, odd, odd, even);
        Matrix powered = base.pow(n).pow(m);
        out.println(powered.a00);
        out.flush();
    }

    long exp(long a, int e) {
        if (e == 1) return a;
        long r = exp(a, e >> 1);
        r = r * r % MOD;
        if ((e & 1) == 1) {
            r = r * a % MOD;
        }
        return r;
    }

    static class Matrix {
        long a00, a01, a10, a11;

        Matrix(long a00, long a01, long a10, long a11) {
            this.a00 = a00;
            this.a01 = a01;
            this.a10 = a10;
            this.a11 = a11;
        }

        Matrix mul(Matrix o) {
            return new Matrix(
                (a00 * o.a00 + a01 * o.a10) % MOD,
                (a00 * o.a01 + a01 * o.a11) % MOD,
                (a10 * o.a00 + a11 * o.a10) % MOD,
                (a10 * o.a01 + a11 * o.a11) % MOD
            );
        }

        Matrix pow(int e) {
            if (e == 1) return this;
            Matrix r = pow(e >> 1);
            r = r.mul(r);
            if ((e & 1) == 1) {
                r = r.mul(this);
            }
            return r;
        }
    }

    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;

        FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
